-- Run in Supabase SQL editor. Service role key must NEVER reach the browser.
create table if not exists public.subscriptions (id bigint generated by default as identity primary key,user_id uuid not null references auth.users(id) on delete cascade,paypal_subscription_id text not null unique,status text not null default 'PENDING',updated_at timestamptz not null default now());
create index if not exists subscriptions_user_status on public.subscriptions(user_id,status);
create table if not exists public.ai_usage (user_id uuid not null references auth.users(id) on delete cascade,day date not null,count integer not null default 0 check(count>=0),primary key(user_id,day));
create table if not exists public.resumes (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null default 'Untitled resume',content jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now());
create index if not exists resumes_user_id on public.resumes(user_id);
alter table public.subscriptions enable row level security;alter table public.ai_usage enable row level security;alter table public.resumes enable row level security;
create policy "read own subscriptions" on public.subscriptions for select to authenticated using ((select auth.uid())=user_id);
create policy "read own usage" on public.ai_usage for select to authenticated using ((select auth.uid())=user_id);
create policy "manage own resumes" on public.resumes for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
